import argparse,base64,hashlib,json,os,re,socket,sys
from pathlib import Path
import task

def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


ARTIFACT_NAMES = ('request.json','wire.partial','wire.bin','frames.json','replies.json','cache.json','manifest.json','validated.json','published.json','failure.json')


def publish_bytes(path, data):
    # Publish by hard link: the final name is created atomically without replacing any winner.
    if path.is_symlink():
        raise ValueError('artifact symlink is not allowed')
    temporary = path.with_name(path.name + '.tmp-' + str(os.getpid()))
    try:
        with temporary.open('xb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path, follow_symlinks=False)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != data:
                raise ValueError('immutable artifact differs: ' + path.name)
    finally:
        temporary.unlink(missing_ok=True)


def write_new(path, value):
    publish_bytes(path, canonical(value) + b'\n')


def prepare_directory(root, generation):
    # A caller-supplied root alias denotes its real directory. Child aliases are never followed.
    root = Path(root).resolve()
    root.mkdir(parents=True, exist_ok=True)
    directory = root / generation
    if directory.is_symlink():
        raise ValueError('generation symlink is not allowed')
    directory.mkdir(exist_ok=True)
    if directory.resolve() != directory:
        raise ValueError('generation escapes root')
    for name in ARTIFACT_NAMES:
        if (directory / name).is_symlink():
            raise ValueError('artifact symlink is not allowed')
    return directory


def b64(value):return base64.b64encode(value).decode('ascii')


def binary(value):
    if not isinstance(value,str):raise ValueError('base64 string required')
    return base64.b64decode(value,validate=True)


def typed(value):
    if value is None:return {'type':'null'}
    if type(value)is int:return {'type':'integer','value':value}
    if isinstance(value,bytes):return {'type':'bytes','base64':b64(value)}
    if isinstance(value,str):return {'type':'text','value':value}
    if isinstance(value,list):return {'type':'array','items':[typed(v)for v in value]}
    if isinstance(value,dict):
        pairs=[[typed(k),typed(v)]for k,v in value.items()]
        pairs.sort(key=lambda pair:canonical(pair[0]))
        return {'type':'map','items':pairs}
    raise ValueError('unsupported decoded value')


def wire(parts):
    return ('*%d\r\n'%len(parts)).encode()+b''.join(('$%d\r\n'%len(p)).encode()+p+b'\r\n'for p in parts)


def requests(value,prefix):
    stages=value['stages']
    if not isinstance(stages,list)or not 1<=len(stages)<=8:raise ValueError('bounded stages')
    result=[]
    for stage in stages:
        if not isinstance(stage,list)or not 1<=len(stage)<=50:raise ValueError('bounded pipeline')
        batch=[]
        for command in stage:
            if not isinstance(command,list):raise ValueError('command array')
            parts=[binary(x)for x in command]
            if (not parts or parts[0]not in (b'GET',b'INCR',b'LPUSH',b'PING')or
                    (parts[0]==b'PING'and len(parts)!=1)or
                    (parts[0]in(b'GET',b'INCR')and len(parts)!=2)or
                    (parts[0]==b'LPUSH'and not 3<=len(parts)<=8)):
                raise ValueError('approved pipeline command')
            if len(parts)>1 and not parts[1].startswith(prefix.encode()):raise ValueError('key outside dedicated prefix')
            if any(len(p)>1048576 for p in parts):raise ValueError('command bulk budget')
            batch.append(parts)
