def outputs(request,frames,prefix):
    commands=[command for stage in requests(request,prefix)for command in stage]
    normals=[f['value']for f in frames]
    if (len(normals)!=len(commands)+3 or not isinstance(normals[0],dict)or
            normals[0].get(b'proto')!=3 or normals[0].get(b'server')!=b'redis' or
