                sock.sendall(wire([b'CLIENT',b'TRACKING',b'ON',b'BCAST',b'PREFIX',args.prefix.encode()]));receive(2)
                expected=2
                for index,batch in enumerate(stages):
                    sock.sendall(b''.join(wire(parts)for parts in batch))
                    expected+=len(batch);receive(expected)
                    print(json.dumps({'phase':'stage','stage':index,'reply_count':expected-2}),flush=True)
                    if sys.stdin.readline()!='continue\n':raise ValueError('stage gate requires continue')
                sock.sendall(wire([b'CLIENT',b'TRACKING',b'OFF']));receive(expected+1)
